std::span<const std::uint8_t> bytes(std::string_view s){return {reinterpret_cast<const std::uint8_t*>(s.data()),s.size()};}
void encodeFixture(Proto* proto){constexpr OpCode map[]={OP_BXOR,OP_BAND,OP_BOR,OP_SHR,OP_SHL,OP_BNOT,OP_UNM,OP_LEN,OP_NOT,OP_JMP,OP_CONCAT,OP_LT,OP_EQ,OP_TEST,OP_LE,OP_CALL,OP_TESTSET,OP_RETURN,OP_TAILCALL,OP_FORPREP,OP_FORLOOP,OP_TFORCALL,OP_TFORLOOP,OP_CLOSURE,OP_SETLIST,OP_EXTRAARG,OP_LOADK,OP_MOVE,OP_LOADBOOL,OP_LOADKX,OP_GETUPVAL,OP_LOADNIL,OP_GETTABLE,OP_GETTABUP,OP_SETUPVAL,OP_SETTABUP,OP_NEWTABLE,OP_SETTABLE,OP_ADD,OP_SELF,OP_MUL,OP_SUB,OP_POW,OP_MOD,OP_IDIV,OP_DIV,OP_VARARG};for(int i=0;i<proto->sizecode;++i){auto& op=proto->code[i];unsigned source=GET_OPCODE(op),target=0;while(target<std::size(map) && static_cast<unsigned>(map[target])!=source)++target;if(target==std::size(map))throw std::runtime_error("Fixture opcode missing");SET_OPCODE(op,target);}for(int i=0;i<proto->sizep;++i)encodeFixture(proto->p[i]);}
void testJassBridge(){auto module=jass::Module::compile(jass::Program::parse({{"lua-bridge.j","type unit extends handle\nnative Record takes integer i, real r, boolean b, string s returns integer\nnative IsNull takes string s returns boolean\nnative UnsupportedResult takes nothing returns unit\nnative Unsupported takes code fn returns nothing\nnative Wait takes real seconds returns nothing\nfunction main takes nothing returns nothing\nendfunction\n","fixture"}}));jass::Runtime vm(std::move(module));int calls=0;vm.bind("Record",[&](auto& runtime,auto args){++calls;if(std::bit_cast<std::int32_t>(args[0].bits)!=-1 || std::bit_cast<float>(args[1].bits)!=1.5f || args[2].bits!=0 || !args[3].text || *args[3].text!="abc")throw std::runtime_error("Lua JASS argument differs");return runtime.integer(-7);});vm.bind("Unsupported",[&](auto& runtime,auto){++calls;return runtime.nothing();});vm.bind("IsNull",[](auto& runtime,auto values){return runtime.boolean(!values[0].text);});vm.bind("UnsupportedResult",[&](auto& runtime,auto){++calls;return runtime.handle("unit",1);});vm.bindSleep("Wait");vm.initialize();LuaRuntime lua;lua.attachJass(vm);auto value=lua.execute(bytes("j=require('jass.common'); old=j.Record; return old(4294967295,1.5,0,'abc')"),"jass-call");if(value.kind!=LuaResult::Kind::Integer || value.integer!=-7 || calls!=1)throw std::runtime_error("Lua JASS native call differs");value=lua.execute(bytes("local a=pcall(function() return j.Unknown end); local b=pcall(function() j.x=1 end); local c=pcall(function() j.Unsupported(function() end) end); local d=pcall(function() j.Wait(0.1) end); local e=pcall(function() j.UnsupportedResult() end); return a or b or c or d or e"),"jass-reject");if(value.kind!=LuaResult::Kind::Boolean || value.boolean || calls!=1)throw std::runtime_error("Unsupported Lua JASS operation accepted");value=lua.execute(bytes("return j.IsNull(nil)"),"jass-null");if(value.kind!=LuaResult::Kind::Boolean || !value.boolean)throw std::runtime_error("Lua JASS null string differs");value=lua.execute(bytes("return j.Record(1)"),"jass-arity");if(value.kind!=LuaResult::Kind::Nil || calls!=1)throw std::runtime_error("Lua JASS missing argument differs");lua.detachJass();value=lua.execute(bytes("local ok=pcall(old,0,0,false,''); return ok"),"jass-detach");if(value.kind!=LuaResult::Kind::Boolean || value.boolean)throw std::runtime_error("Detached Lua JASS closure remained callable");lua.attachJass(vm);value=lua.execute(bytes("local ok=pcall(old,0,0,false,''); return ok"),"jass-reattach");if(value.kind!=LuaResult::Kind::Boolean || value.boolean)throw std::runtime_error("Stale Lua JASS closure survived reattachment");lua.detachJass();}
int save(lua_State*,const void* data,size_t size,void* target){auto& out=*static_cast<std::vector<std::uint8_t>*>(target);auto first=static_cast<const std::uint8_t*>(data);out.insert(out.end(),first,first+size);return 0;}
